    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone
    if nanoseconds is None:
        return None
    try:
        # Convert nanoseconds to seconds
        seconds = nanoseconds / 1_000_000_000
    except (TypeError, ValueError) as exc:
        raise ValueError(f"nanoseconds must be an integer or float representing nanoseconds, got {nanoseconds!r}") from exc
    try:
        # If tz is None, use UTC by default to avoid local timezone ambiguity
        if tz is None:
            dt = datetime.fromtimestamp(seconds, tz=timezone.utc)
        else:
