def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`."""
        # Basic safety checks
        if not hasattr(self, "points"):
            raise AttributeError("The object does not provide a 'points' attribute.")

        if header is not None and not isinstance(header, str):
            raise TypeError("header must be a string or None")

        lines = []
        if header is not None:
            lines.append(header)

        try:
            for point in self.points:
                # Expect point as (coord, value)
                if not isinstance(point, (list, tuple)) or len(point) != 2:
                    raise ValueError("Each point must be a tuple/list of (coord, value)")

                coord, value = point

                # Convert coordinate
                if isinstance(coord, (list, tuple)):
                    coord_items = [str(c) for c in coord]
                else:
                    coord_items = [str(coord)]

                coord_str = separator.join(coord_items)

                # Convert value
                # Value can be iterable or single
                if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
                    value_items = [str(v) for v in value]
                else:
                    value_items = [str(value)] if value is not None else []

                value_str = separator.join(value_items)

                if value_str:
                    line = coord_str + separator + value_str
                else:
                    line = coord_str

                lines.append(line)

        except Exception as exc:
            # Return a readable error message in the CSV output
            # rather than throwing an exception that would break
            # the calling code that might rely on to_csv for diagnostics.
            error_line = f"Error converting point to CSV: {exc}"
            if lines:
                lines.append(error_line)
            else:
                lines = [error_line]

        return "\n".join(lines)

