    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation of inputs
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError as exc:
        raise ValueError("Both bins and edges must be array-like") from exc

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    total = 0.0
    for value, left, right in zip(bins_list, edges_list, edges_list[1:]):
        try:
            width = right - left
            total += value * width
        except Exception as exc:
            raise ValueError(f"Non-numeric bin value or edge encountered: {exc}") from exc

    return total

