    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []

    # helpers to import modules lazily
    def _load_json(path):
        json_mod = __import__('json')
        with open(path, 'r', encoding='utf-8') as f:
            return json_mod.load(f)

    def _load_yaml(path):
        yaml_mod = __import__('yaml')
        with open(path, 'r', encoding='utf-8') as f:
            return yaml_mod.safe_load(f)

    def _load_ini(path):
        cfg_mod = __import__('configparser')
        parser = cfg_mod.ConfigParser()
        parser.read(path, encoding='utf-8')
        # convert to nested dict
        cfg = {}
        for section in parser.sections():
            cfg[section] = dict(parser.items(section))
        return cfg

    def resolve_env_vars(value):
        if isinstance(value, str):
            # replace ${VAR} with environment variable
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return re.sub(r'\$\{([^}]+)\}', repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(x) for x in value]
        return value

    for fname in config_filenames:
        try:
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.json':
                config = _load_json(fname)
            elif ext in ('.yaml', '.yml'):
                config = _load_yaml(fname)
            elif ext in ('.ini', '.cfg'):
                config = _load_ini(fname)
            else:
                # unsupported file type
                raise ValueError(f'Unsupported configuration file type: {ext}')
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Failed to parse configuration file "{fname}": {e}',
                args=None,
                exc_info=None)
            log_records.append(record)
            continue

        # apply overrides if any
        if overrides:
            override = overrides.get(fname)
            if override and isinstance(override, dict):
                if isinstance(config, dict):
                    config.update(override)
                else:
                    # cannot override non-dict config
