    if data_attr is None:
        raise AttributeError("Histogram data attribute not found for rescaling.")

    # Scale the data in place
    if isinstance(data_attr, dict):
        for key in data_attr:
            data_attr[key] *= factor
    else:
        # Assume iterable with numeric items
        try:
            for i in range(len(data_attr)):
                data_attr[i] *= factor
        except Exception as exc:
            raise TypeError("Histogram data is not a scalable sequence") from exc

    # Update cached scale
    self._scale = target_scale
    return target_scale

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Validate new scale value
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric.")
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        # Assuming LenaValueError is defined elsewhere in the module
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale each field's last coordinate and associated errors
    fields = getattr(self, "fields", None)
    if fields is None:
        # Attempt to guess common attribute names for fields
        if hasattr(self, "grid"):
            fields = getattr(self, "grid")
        else:
            fields = []

    for field in fields or []:
        # Rescale data points
        # Common containers might be numpy arrays or lists of tuples
        # Attempt to find numeric arrays
        data = None
        if hasattr(field, "data"):
            data = field.data
        elif hasattr(field, "points"):
            data = field.points
        if data is None:
            continue

        try:
            import numpy as np
            if isinstance(data, np.ndarray):
                # Ensure array has at least one dimension
                if data.ndim >= 1:
                    data[:, -1] *= factor
                if hasattr(field, "errors") and field.errors is not None:
                    if isinstance(field.errors, np.ndarray):
                        field.errors[:, -1] *= factor
                    elif isinstance(field.errors, list):
                        for err in field.errors:
                            if hasattr(err, "__iter__"):
                                err[-1] *= factor
            else:
                # Assume data is list-like of tuples or lists
                new_points = []
                for pt in data:
                    pt = list(pt)
                    pt[-1] *= factor
                    new_points.append(tuple(pt))
                if hasattr(field, "points"):
                    field.points = new_points
                # Rescale errors if present
                if hasattr(field, "errors") and field.errors is not None:
                    new_errors = []
                    for err in field.errors:
                        err = list(err)
                        err[-1] *= factor
                        new_errors.append(tuple(err))
                    field.errors = new_errors
        except Exception:
            # If any custom field implementation fails, skip silently
            continue

    # Update the graph's scale
    self._scale = other
    return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new value requested
    if other is None:
        return getattr(self, "_scale", None)

    # Ensure other is numeric
    try:
        new_scale = float(other)
    except Exception as exc:
        raise ValueError("Scale must be a numeric value.") from exc

    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

    # Compute scaling factor
    factor = new_scale / current_scale

    # Identify the fields of the graph
    fields = getattr(self, "fields", None)
    if fields is None:
        fields = getattr(self, "_fields", None)
    if not fields or not isinstance(fields, (list, tuple)):
        raise ValueError("Graph does not contain any fields to rescale.")

    # Rescale the last coordinate field
    last_field = fields[-1]
    # Rescale the coordinate values
    if hasattr(last_field, "values"):
        try:
            last_field.values = [v * factor for v in last_field.values]
        except Exception:
            # If values are numpy arrays or other iterable
            try:
                last_field.values *= factor
            except Exception:
                pass
    elif hasattr(last_field, "data"):
        try:
            last_field.data = [v * factor for v in last_field.data]
        except Exception:
            try:
                last_field.data *= factor
            except Exception:
                pass

    # Rescale the errors (if any)
    if hasattr(last_field, "errors") and last_field.errors is not None:
        try:
            last_field.errors = [e * factor for e in last_field.errors]
        except Exception:
            try:
                last_field.errors *= factor
            except Exception:
                pass

    # Update the stored scale
    setattr(self, "_scale", new_scale)
    return self.

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be ``"left"`` (default), ``"right"`` and ``"middle"``.

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Default make_value if not provided
    if make_value is None:
        make_value = lambda bin_: bin_

    # Resolve scale
    if scale is True:
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Determine the collection of bin contents
    try:
        if hasattr(hist, "bins"):
            bins = hist.bins
        else:
            bins = hist
        # Ensure we can iterate
        iter(bins)
    except TypeError:
        raise TypeError("hist must be an iterable of bin contents or have a 'bins' attribute")

    # Get bin edges if available, otherwise we approximate with indices
    try:
        edges = getattr(hist, "edges", None)
        if edges is not None:
            # Convert to list to support indexing
            edges = list(edges)
    except Exception:
        edges = None

    # Function to compute coordinate for a given bin index
    def coordinate(idx):
        if edges is not None:
            if get_coordinate == "left":
                return edges[idx]
            elif get_coordinate == "right":
                return edges[idx + 1]
            elif get_coordinate == "middle":
                return (edges[idx] + edges[idx + 1]) / 2.0
            else:
                raise ValueError(
                    f"Unknown get_coordinate value '{get_coordinate}'. "
                    "Use 'left', 'right', or 'middle'."
                )
        # Fallback: use the index as the coordinate
        if get_coordinate == "left":
            return float(idx)
        elif get_coordinate == "right":
            return float(idx + 1)
        elif get_coordinate == "middle":
            return float(idx) + 0.5
        else:
            raise ValueError(
                f"Unknown get_coordinate value '{get_coordinate}'. "
                "Use 'left', 'right', or 'middle'."
            )

    # Prepare graph instance
    try:
        # It is expected that there is a Graph class available in the import context
        graph = Graph()
    except NameError:
        raise NameError("Graph class must be defined in the surrounding context.")

    # Assign graph attributes if they exist
    if hasattr(graph, "scale"):
        graph.scale = scale_val
    if hasattr(graph, "field_names"):
        graph.field_names = list(field_names)
    elif hasattr(graph, "fields"):
        graph.fields = list(field_names)
    else:
        # If graph does not have fields attribute, we set attribute anyway
        setattr(graph, "field_names", list(field_names))

    # Prepare container for points
    try:
        graph.points
    except AttributeError:
        # Graph might manage points via add_point method instead
        pass

    points = []
    for i, bin_content in enumerate(bins):
        try:
            x_coord = coordinate(i)
        except Exception as e:
            raise ValueError(f"Error computing coordinate for bin index {i}: {e}")

        try:
            y_vals = make_value(bin_content)
        except Exception as e:
            raise ValueError(f"Error applying make_value to bin index {i}: {e}")

        # Normalize y_vals to a tuple
        if not isinstance(y_vals, (tuple, list)):
            y_vals = (y_vals,)

        # Build the point tuple: coordinate + y values
        point = (x_coord,) + tuple(y_vals)

        # Validate the number of fields
        if len(point) != len(field_names):
            raise ValueError(
                f"Number of fields {len(point)} does not match field_names "
                f"{len(field_names)} at bin index {i}."
            )
        points.append(point)

    # Add points to graph
    if hasattr(graph, "add_point"):
        for p in points:
            graph.add_point(p)
    elif hasattr(graph, "points"):
        graph.points.extend(points)
    else:
        # Fallback: assign points attribute
        setattr(graph, "points", points)

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use
    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Extract edges and bin values from the histogram.
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        try:
            edges = getattr(hist, "bin_edges")
        except AttributeError:
            raise AttributeError(
                "Histogram object must provide an 'edges' or 'bin_edges' attribute."
            )
    try:
        values = getattr(hist, "values")
    except AttributeError:
        try:
            values = getattr(hist, "data")
        except AttributeError:
            raise AttributeError(
                "Histogram object must provide a 'values' or 'data' attribute."
            )

    num_bins = len(values)
    if len(edges) != num_bins + 1:
        raise ValueError(
            "Histogram 'edges' length must be one more than number of bins."
        )

    # Determine which edge to use for the X coordinate.
    if get_coordinate == "left":
        coord_index = lambda i: edges[i]
    elif get_coordinate == "right":
        coord_index = lambda i: edges[i + 1]
    elif get_coordinate == "middle":
        coord_index = lambda i: (edges[i] + edges[i + 1]) / 2
    else:
        raise ValueError(
            "Parameter 'get_coordinate' must be either 'left', 'right' or 'middle'."
        )

    # Resolve scale.
    if scale is True:
        scale = getattr(hist, "scale", None)

    # Build points for the graph.
    points = []
    for i in range(num_bins):
        coord = coord_index(i)
        val = values[i]
        if make_value is not None:
            try:
                val = make_value(val)
            except Exception as exc:
                raise RuntimeError(
                    f"make_value failed for bin {i} with value {val}"
                ) from exc

        # Normalise val to a tuple of values.
        if isinstance(val, (list, tuple)):
            val_tuple = tuple(val)
        else:
            val_tuple = (val,)

        # Ensure the number of fields matches the data dimensions.
        if len(val_tuple) + 1 != len(field_names):
            raise ValueError(
                f"Inconsistent field count for bin {i}: "
                f"expected {len(field_names)} but got {len(val_tuple) + 1}."
            )

        point = {field_names[0]: coord}
        for fn, vv in zip(field_names[1:], val_tuple):
            point[fn] = vv
        points.append(point)

    # Return a simple representation of a graph.
    return {"points": points, "scale": scale}

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine scale for graph
    try:
        if scale is True:
            scale_value = getattr(hist, "scale", None)
        else:
            scale_value = scale
    except Exception:
        scale_value = None

    n_fields = len(field_names)

    # Simple graph implementation
    class Graph:
        def __init__(self, scale):
            self.scale = scale
            self.field_names = field_names
            self.points = []

        def add_point(self, *args):
            if len(args) != len(self.field_names):
                raise ValueError(f"Expected {len(self.field_names)} values, got {len(args)}")
            self.points.append(args)

    graph = Graph(scale=scale_value)

    # Iterate over histogram bins
    try:
        bins_iter = iter(hist)
    except TypeError:
        raise ValueError("Histogram object must be iterable over bins")

    for bin_item in bins_iter:
        # Determine bin boundaries
        if hasattr(bin_item, "left") and hasattr(bin_item, "right"):
            left, right = bin_item.left, bin_item.right
        elif isinstance(bin_item, tuple) and len(bin_item) >= 2:
            left, right = bin_item[0], bin_item[1]
        else:
            raise ValueError("Histogram bin must have left/right attributes or be a tuple with at least two elements")

        if get_coordinate == "left":
            x_coord = left
        elif get_coordinate == "right":
            x_coord = right
        elif get_coordinate == "middle":
            x_coord = (left + right) / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        # Get bin content
        if hasattr(bin_item, "content"):
            bin_content = bin_item.content
        elif isinstance(bin_item, tuple) and len(bin_item) >= 3:
            bin_content = bin_item[2]
        else:
            raise ValueError("Histogram bin must contain content as attribute 'content' or third element in the tuple")

        # Compute point value(s)
        if make_value is None:
            value = bin_content
        else:
            value = make_value(bin_content)

        if isinstance(value, (list, tuple)):
            point_vals = (x_coord,) + tuple(value)
        else:
            point_vals = (x_coord, value)

        if len(point_vals) != n_fields:
            raise ValueError(f"Number of fields {len(point_vals)} does not match expected {n_fields}")

        graph.add_point(*point_vals)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        from zope.interface import Invalid
    except Exception:
        # In case zope.interface is not available, raise a standard
        # exception with an informative message.
        raise RuntimeError("zope.interface is required for _verify")
    import inspect

    errors = []

    # 1. Check that candidate declares it provides the iface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide {iface}")

    # 2. Check methods
    try:
        methods = iface.methods()
    except Exception:
        methods = {}
    for name, iface_method in methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        # Compare signatures if possible
        try:
            sig_iface = inspect.signature(iface_method)
            sig_cand = inspect.signature(cand_method)
            if sig_iface.parameters != sig_cand.parameters:
                errors.append(
                    f"Signature mismatch for method '{name}': expected {sig_iface}, got {sig_cand}"
                )
        except Exception as exc:
            errors.append(f"Could not inspect signature of '{name}': {exc}")

    # 3. Check attributes
    try:
        attributes = iface.attributes()
    except Exception:
        attributes = {}
    for name in attributes.keys():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")

    # 4. Raise or return
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("; ".join(errors))
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    errors = []

    # If tentative, skip the providedBy check
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(f"{candidate!r} does not provide {iface!r}")

    # Helper to compare signatures lightly
    def _signature_match(sig_src, sig_cand):
        params_src = sig_src.parameters
        params_cand = sig_cand.parameters

        # Ensure all non-var parameters from source exist in candidate
        for name, param in params_src.items():
            if param.kind in (inspect.Parameter.VAR_POSITIONAL,
                              inspect.Parameter.VAR_KEYWORD):
                continue
            if name not in params_cand:
                return False

        # We will allow candidate to have extra parameters; this keeps checking lenient
        return True

    # Inspect methods defined in the interface
    try:
        interface_methods = getattr(iface, 'methods', None) or getattr(iface, '_methods', None)
    except Exception:
        interface_methods = None

    if interface_methods is None:
        # As a fallback, discover all callables in the interface namespace
        interface_methods = []
        for name in dir(iface):
            attr = getattr(iface, name, None)
            if callable(attr) and not name.startswith('_'):
                interface_methods.append(name)

    for name in interface_methods:
        cand_method = getattr(candidate, name, None)
        if cand_method is None:
            errors.append(f"Missing method {name!r} required by {iface!r}")
            continue

        # Verify signature if possible
        try:
            src_sig = inspect.signature(getattr(iface, name))
            cand_sig = inspect.signature(cand_method)
            if not _signature_match(src_sig, cand_sig):
                errors.append(
                    f"Signature mismatch for {name!r}: expected {src_sig}, got {cand_sig}"
                )
        except (ValueError, TypeError):
            # Skeleton signatures are not inspectable; ignore
            pass

    # Inspect required attributes
    try:
        required_attrs = getattr(iface, 'requiredAttributes', None)
        if required_attrs is None:
            required_attrs = getattr(iface, 'attributes', None)
    except Exception:
        required_attrs = None

    if required_attrs:
        for name in required_attrs:
            if not hasattr(candidate, name):
                errors.append(f"Missing required attribute {name!r} for {iface!r}")
            else:
                # Optional: we could check that the attribute is not callable if
                # interface expects a non-callable
                attr = getattr(candidate, name)
                if callable(attr):
                    # determine if interface expects callable
                    try:
                        iface_attr = getattr(iface, name)
                        if not callable(iface_attr):
                            errors.append(
                                f"Attribute {name!r} is callable but interface expects non-callable"
                            )
                    except Exception:
                        pass

    # If no errors, verification passed
    if not errors:
        return True

    # If only one error, raise it directly
    if len(errors) == 1:
        # Raise a zope.interface.Invalid with the single error
        raise zope.interface.Invalid(iface, candidate, errors=[errors[0]])

    # Multiple errors: aggregate them into a single exception
    msg = "; ".join(errors)
    raise zope.interface.Invalid(iface, candidate, errors=errors)

